import Fragment from "sap/ui/core/Fragment";
import Filter from "sap/ui/model/Filter";
import FilterOperator from "sap/ui/model/FilterOperator";
import JSONModel from "sap/ui/model/json/JSONModel";
import type Dialog from "sap/m/Dialog";
import type Table from "sap/m/Table";
import type Control from "sap/ui/core/Control";
import type Event from "sap/ui/base/Event";
import type Context from "sap/ui/model/odata/v4/Context";
import type ODataListBinding from "sap/ui/model/odata/v4/ODataListBinding";
import type Button from "sap/m/Button";
import type Admin from "../Admin.controller";
import AdminOrderService, { DeliveryInput, DeliveryType } from "../../service/AdminOrderService";
import { OrderStatus } from "../../model/formatter";
import type { EditableOrder } from "./OrderEditSection";
import type { ReturnableOrder } from "./OrderReturnSection";
import type { ComposableOrder } from "./WhatsappComposer";

const ALL_STATUSES = "ALL";
const ALL = "ALL";
const SEARCH_DELAY = 300;
const DIGITS_ONLY = /^\d+$/;

interface OrderFilters {
    status: string;
    search: string;
    channel: string;
    fulfillment: string;
    from: Date | null;
    to: Date | null;
}
const FULL_SCREEN_MAX_WIDTH = 600;
const ORDER_EXPAND = "Items,Promotions,Returns($expand=Items;$orderby=createdAt)";
const CHANGE_PARAMETERS = {
    $select: "ID,Number,CouponCode",
    $expand: "Items($select=ID,Variant_ID,ImageId,ProductName,ColorName,Size,Quantity,UnitPrice),Returns($select=ID;$expand=Items($select=ID,Kind,OrderItem_ID,Replacement_ID,ImageId,ProductName,ColorName,Size,Quantity)),Promotions($select=ID,CouponCode)"
};

type DialogOrder = EditableOrder & ReturnableOrder & ComposableOrder;

export default class OrdersSection {

    public readonly deliveryModel = new JSONModel(this.emptyDelivery());

    private dialog?: Dialog;

    private deliveryDialog?: Dialog;

    private returnDetailsDialog?: Dialog;

    private deleteDialog?: Dialog;

    private deleteIds: string[] = [];

    constructor(private readonly controller: Admin) { }

    public readonly filterModel = new JSONModel(this.emptyFilters());

    public readonly stateModel = new JSONModel({ selectedCount: 0, restoreStock: true, confirmText: "", deleting: false });

    private searchTimer?: ReturnType<typeof setTimeout>;

    public onStatusPress = (event: Event): void => {
        this.filterModel.setProperty("/status", ((event.getSource() as Button).data("status") as string | null) ?? ALL_STATUSES);
        this.applyFilters();
    };

    public onSearch = (): void => {
        clearTimeout(this.searchTimer);
        this.searchTimer = setTimeout(() => this.applyFilters(), SEARCH_DELAY);
    };

    public onFilterChange = (): void => {
        this.applyFilters();
    };

    public onClearFilters = (): void => {
        this.filterModel.setData({ ...this.emptyFilters(), status: this.filterModel.getProperty("/status") });
        this.applyFilters();
    };

    public onRefresh = (): void => {
        this.refresh();
    };

    public refresh(): void {
        this.getTableBinding()?.refresh();
    }

    public refreshOpenOrder(): void {
        this.dialog?.getElementBinding()?.refresh();
        this.refresh();
    }

    public onEditItems = async (): Promise<void> => {
        const order = await this.loadChangeableOrder();

        if (order) {
            await this.controller.orderEdit.open(order);
        }
    };

    public onRegisterReturn = async (): Promise<void> => {
        const order = await this.loadChangeableOrder();

        if (order) {
            await this.controller.orderReturn.open(order);
        }
    };

    public onOrderPress = async (event: Event): Promise<void> => {
        const context = (event.getSource() as Control).getBindingContext() as Context;
        const dialog = await this.getDialog();

        dialog.bindElement({ path: context.getPath(), parameters: { $expand: ORDER_EXPAND } });
        dialog.setStretch(window.innerWidth < FULL_SCREEN_MAX_WIDTH);
        dialog.open();
    };

    public onItemPress = (event: Event): void => {
        const productId = (event.getSource() as Control).getBindingContext()?.getProperty("Product_ID") as string | undefined;

        if (productId) {
            this.onCloseDialog();
            this.controller.navTo("product", { productId });
        }
    };

    public onCloseDialog = (): void => {
        this.dialog?.close();
    };

    public onStartService = (): Promise<boolean> => this.changeStatus(OrderStatus.InService, "orderStatusChanged");

    public onComplete = (): Promise<boolean> => this.changeStatus(OrderStatus.Completed, "orderStatusChanged");

    public onCancel = async (): Promise<void> => {
        if (await this.controller.confirm("confirmCancelOrder", [this.getDialogOrder().Number])) {
            await this.changeStatus(OrderStatus.Cancelled, "orderCancelled");
        }
    };

    public onOpenDeliveryDialog = async (): Promise<void> => {
        this.deliveryModel.setData(this.emptyDelivery());
        (await this.getDeliveryDialog()).open();
    };

    public onReturnDetails = async (event: Event): Promise<void> => {
        const context = (event.getSource() as Control).getBindingContext() as Context;

        if (!this.returnDetailsDialog) {
            this.returnDetailsDialog = await this.loadFragment("ReturnDetailsDialog");
        }

        this.returnDetailsDialog.bindElement({ path: context.getPath(), parameters: { $expand: "Items" } });
        this.returnDetailsDialog.setStretch(window.innerWidth < FULL_SCREEN_MAX_WIDTH);
        this.returnDetailsDialog.open();
    };

    public onReturnItemPress = (event: Event): void => {
        const productId = (event.getSource() as Control).getBindingContext()?.getProperty("Product_ID") as string | undefined;

        if (productId) {
            this.onCloseReturnDetails();
            this.onCloseDialog();
            this.controller.navTo("product", { productId });
        }
    };

    public onCloseReturnDetails = (): void => {
        this.returnDetailsDialog?.close();
    };

    public onCloseDeliveryDialog = (): void => {
        this.deliveryDialog?.close();
    };

    public onConfirmDelivery = async (): Promise<void> => {
        const delivery = this.deliveryModel.getData() as DeliveryInput;

        if (await this.changeStatus(OrderStatus.OutForDelivery, "orderStatusChanged", delivery)) {
            this.deliveryDialog?.close();
        }
    };

    public onWhatsapp = (): void => {
        void this.controller.whatsapp.open(this.getDialogOrder());
    };

    public onSelectionChange = (): void => {
        this.stateModel.setProperty("/selectedCount", this.getTable().getSelectedContexts().length);
    };

    public onDeleteSelected = (): Promise<void> => {
        const orderIds = (this.getTable().getSelectedContexts() as Context[]).map((context) => context.getProperty("ID") as string);

        if (orderIds.length === 0) {
            return Promise.resolve();
        }

        return this.openDeleteDialog(orderIds);
    };

    public onDeleteOpenOrder = (): Promise<void> => this.openDeleteDialog([this.getDialogOrder().ID]);

    public onCancelDelete = (): void => {
        if (this.stateModel.getProperty("/deleting") as boolean) {
            return;
        }

        this.deleteDialog?.close();
    };

    public onConfirmDelete = async (): Promise<void> => {
        const restoreStock = this.stateModel.getProperty("/restoreStock") as boolean;
        const count = this.deleteIds.length;

        this.stateModel.setProperty("/deleting", true);

        try {
            await this.controller.runBusy(() => new AdminOrderService(this.controller.getAdminModel()).deleteOrders(this.deleteIds, restoreStock));

            this.afterDelete(count);
        } catch (error) {
            this.controller.handleError(error, "ordersDeleteError");
        } finally {
            this.stateModel.setProperty("/deleting", false);
        }
    };

    private async changeStatus(status: OrderStatus, successKey: string, delivery?: DeliveryInput): Promise<boolean> {
        const order = this.getDialogOrder();

        try {
            await this.controller.runBusy(() => new AdminOrderService(this.controller.getAdminModel()).changeStatus(order.ID, status, delivery));

            this.controller.showToast(successKey, [order.Number]);
            this.refreshOpenOrder();

            return true;
        } catch (error) {
            this.controller.handleError(error, "orderStatusError");

            return false;
        }
    }

    private async openDeleteDialog(orderIds: string[]): Promise<void> {
        this.deleteIds = orderIds;
        this.stateModel.setProperty("/restoreStock", true);
        this.stateModel.setProperty("/confirmText", this.controller.getText("deleteOrdersConfirm", [orderIds.length]));

        (await this.getDeleteDialog()).open();
    }

    private afterDelete(count: number): void {
        this.deleteDialog?.close();
        this.onCloseDialog();
        this.dialog?.unbindElement();
        this.getTable().removeSelections(true);
        this.stateModel.setProperty("/selectedCount", 0);
        this.refresh();
        void this.controller.reports.load();
        this.controller.showToast("ordersDeleted", [count]);
    }

    private async loadChangeableOrder(): Promise<DialogOrder | undefined> {
        const path = this.dialog?.getBindingContext()?.getPath() as string;

        try {
            return await this.controller.runBusy(() => this.controller.getAdminModel()
                .bindContext(path, undefined, CHANGE_PARAMETERS)
                .requestObject() as Promise<DialogOrder>);
        } catch (error) {
            this.controller.handleError(error, "orderLoadError");

            return undefined;
        }
    }

    private applyFilters(): void {
        const criteria = this.filterModel.getData() as OrderFilters;
        const filters: Filter[] = [];
        const search = criteria.search.trim();

        if (criteria.status !== ALL_STATUSES) {
            filters.push(new Filter("Status", FilterOperator.EQ, criteria.status));
        }

        if (search) {
            filters.push(this.searchFilter(search));
        }

        if (criteria.channel !== ALL) {
            filters.push(new Filter("Channel", FilterOperator.EQ, criteria.channel));
        }

        if (criteria.fulfillment !== ALL) {
            filters.push(new Filter("FulfillmentType", FilterOperator.EQ, criteria.fulfillment));
        }

        if (criteria.from) {
            filters.push(new Filter("createdAt", FilterOperator.GE, this.startOfDay(criteria.from).toISOString()));
        }

        if (criteria.to) {
            filters.push(new Filter("createdAt", FilterOperator.LT, this.startOfDay(criteria.to, 1).toISOString()));
        }

        this.getTableBinding().filter(filters.length ? new Filter({ filters, and: true }) : []);
    }

    private searchFilter(search: string): Filter {
        const text = (path: string, value = search): Filter => new Filter({ path, operator: FilterOperator.Contains, value1: value, caseSensitive: false });
        const alternatives = [text("CustomerName"), text("CustomerEmail")];
        const digits = search.replace(/\D/g, "");

        if (digits) {
            alternatives.push(text("CustomerPhone", digits));
        }

        if (DIGITS_ONLY.test(search)) {
            alternatives.push(new Filter("Number", FilterOperator.EQ, Number(search)));
        }

        return new Filter({ filters: alternatives, and: false });
    }

    private startOfDay(date: Date, addDays = 0): Date {
        return new Date(date.getFullYear(), date.getMonth(), date.getDate() + addDays);
    }

    private emptyFilters(): OrderFilters {
        return { status: ALL_STATUSES, search: "", channel: ALL, fulfillment: ALL, from: null, to: null };
    }

    private emptyDelivery(): DeliveryInput {
        return { DeliveryType: DeliveryType.UberFlash, CourierName: "", VehiclePlate: "", DeliveryNotes: "" };
    }

    private getDialogOrder(): DialogOrder {
        return this.dialog?.getBindingContext()?.getObject() as DialogOrder;
    }

    private getTable(): Table {
        return this.controller.byControlId<Table>("ordersTable");
    }

    private getTableBinding(): ODataListBinding {
        return this.getTable().getBinding("items") as ODataListBinding;
    }

    private async getDialog(): Promise<Dialog> {
        if (!this.dialog) {
            this.dialog = await this.loadFragment("OrderDialog");
        }

        return this.dialog;
    }

    private async getDeliveryDialog(): Promise<Dialog> {
        if (!this.deliveryDialog) {
            this.deliveryDialog = await this.loadFragment("DeliveryDialog");
            this.deliveryDialog.setModel(this.deliveryModel, "delivery");
        }

        return this.deliveryDialog;
    }

    private async getDeleteDialog(): Promise<Dialog> {
        if (!this.deleteDialog) {
            this.deleteDialog = await this.loadFragment("DeleteOrdersDialog");
        }

        return this.deleteDialog;
    }

    private async loadFragment(name: string): Promise<Dialog> {
        const view = this.controller.getView();
        const dialog = await Fragment.load({
            id: view?.getId(),
            name: `apps.dflc.benditalook.view.fragments.${name}`,
            controller: this.controller
        }) as Dialog;

        view?.addDependent(dialog);

        return dialog;
    }

}
